{
  "schemaVersion": "0.2",
  "slug": "gauge",
  "name": "Gauge",
  "family": "F",
  "status": "experimental",
  "purpose": "Shows a single value on a semicircular dial against a maximum.",
  "scenarios": [
    "CPU utilization dial",
    "Score against target",
    "Capacity usage indicator"
  ],
  "props": {
    "value": {
      "type": "number",
      "required": true,
      "description": "Current value."
    },
    "max": {
      "type": "number",
      "required": false,
      "description": "Maximum value.",
      "default": 100
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible description of the gauge."
    },
    "valueLabel": {
      "type": "string",
      "required": false,
      "description": "Formatted value text shown in the dial."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Dial rendered with the current value."
    }
  ],
  "composition": {
    "allowedParents": [
      "card",
      "kpi-dashboard",
      "page"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use a gauge for negative ranges.",
    "Do not place multiple gauges in a row without aligned max values."
  ],
  "a11y": {
    "role": "meter",
    "keyboard": [],
    "focus": "Not focusable.",
    "labeling": "role=meter with aria-valuemin/max/now exposes the value.",
    "wcag": [
      "1.1.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Fixed intrinsic size that scales down on compact.",
    "breakpoints": {
      "compact": "Scaled down dial.",
      "medium": "Intrinsic size.",
      "large": "Intrinsic size."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "gauge",
    "states": [
      "default"
    ],
    "intents": [
      "visualize-data",
      "show-progress"
    ]
  }
}

import './styles.css'

export interface GaugeProps {
  value: number
  max?: number
  label: string
  valueLabel?: string
  className?: string
}

const RADIUS = 70
const CENTER = 80

export function Gauge({ value, max = 100, label, valueLabel, className }: GaugeProps) {
  const classes = ['cu-gauge', className].filter(Boolean).join(' ')
  const clamped = Math.min(max, Math.max(0, value))
  const percent = max > 0 ? (clamped / max) * 100 : 0
  const startX = CENTER - RADIUS
  const endX = CENTER + RADIUS

  return (
    <div className={classes} data-ai-role="gauge" data-ai-intent="visualize-data" data-ai-state="default">
      <svg
        className="cu-gauge__svg"
        viewBox={`0 0 ${CENTER * 2} ${CENTER + 12}`}
        role="meter"
        aria-label={label}
        aria-valuemin={0}
        aria-valuemax={max}
        aria-valuenow={clamped}
      >
        <path
          className="cu-gauge__track"
          d={`M ${startX} ${CENTER} A ${RADIUS} ${RADIUS} 0 0 1 ${endX} ${CENTER}`}
          pathLength={100}
        />
        <path
          className="cu-gauge__fill"
          d={`M ${startX} ${CENTER} A ${RADIUS} ${RADIUS} 0 0 1 ${endX} ${CENTER}`}
          pathLength={100}
          strokeDasharray={`${percent} 100`}
        />
        <text className="cu-gauge__value" x={CENTER} y={CENTER - 8} textAnchor="middle">
          {valueLabel ?? String(clamped)}
        </text>
      </svg>
    </div>
  )
}

.cu-gauge {
  display: inline-block;
  color: var(--cu-color-fg-default);
}

.cu-gauge__svg {
  display: block;
  inline-size: calc(var(--cu-space-3) * 20);
  max-inline-size: 100%;
  block-size: auto;
}

.cu-gauge__track {
  fill: none;
  stroke: var(--cu-color-border-default);
  stroke-width: 10;
  stroke-linecap: round;
}

.cu-gauge__fill {
  fill: none;
  stroke: var(--cu-color-palette-brand);
  stroke-width: 10;
  stroke-linecap: round;
}

.cu-gauge__value {
  fill: var(--cu-color-fg-default);
  font-size: 1.25rem;
  font-weight: 600;
}
